<script setup>
import {Head,useForm} from '@inertiajs/vue3';import {computed,ref} from 'vue';import AppShell from '@/Layouts/AppShell.vue';import SettingsNav from '@/Components/SettingsNav.vue';import PageHeader from '@/Components/PageHeader.vue';import UiAlert from '@/Components/UiAlert.vue';
const p=defineProps({section:String,settings:Object,availableImages:Array,currencies:Object,imageLimit:Number,canManagePayments:Boolean}),picker=ref(false),editor=ref(false),preview=ref(p.settings.cover_url||null);const form=useForm({...p.settings,cover:null,remove_cover:false,image_ids:[...p.settings.image_ids],services:p.settings.services.map(x=>({...x}))});const chosen=computed(()=>form.image_ids.map(id=>p.availableImages.find(x=>x.id===id)).filter(Boolean));
function cover(e){let f=e.target.files?.[0];if(f){form.cover=f;form.remove_cover=false;preview.value=URL.createObjectURL(f)}}function toggle(id){let i=form.image_ids.indexOf(id);if(i>=0)form.image_ids.splice(i,1);else if(form.image_ids.length<p.imageLimit)form.image_ids.push(id)}function move(a,d,list=form.image_ids){let b=a+d;if(b>=0&&b<list.length)[list[a],list[b]]=[list[b],list[a]]}function save(){form.transform(d=>({...d,_method:'put'})).post('/settings/portfolio',{forceFormData:true,preserveScroll:true})}
</script>
<template><AppShell><Head title="Portfolio Settings"/><div class="lp-page"><PageHeader eyebrow="Settings" title="Portfolio" description="Build and publish your LensPic photography portfolio."/><div class="mt-8 grid gap-6 lg:grid-cols-[240px_1fr]"><SettingsNav :section="section"/><form class="space-y-6" @submit.prevent="save"><section class="lp-card space-y-5 p-5 sm:p-7"><div class="flex flex-wrap justify-between gap-3"><h2 class="text-xl font-bold">Portfolio</h2><div class="flex gap-3"><a class="btn-secondary" target="_blank" href="/settings/portfolio/preview">View Demo</a><button class="btn-primary" :disabled="form.processing">Save</button></div></div><div class="grid gap-5 md:grid-cols-2"><label class="lp-label">Portfolio Name<input v-model.trim="form.name" class="field mt-2"><small class="text-rose-600">{{form.errors.name}}</small></label><label class="lp-label">Website URL<input v-model.trim="form.website_url" class="field mt-2" placeholder="https://example.com"><small class="text-rose-600">{{form.errors.website_url}}</small></label></div><label class="lp-label">About Us<textarea v-model="form.about_us" class="field mt-2 min-h-32"></textarea><small class="text-rose-600">{{form.errors.about_us}}</small></label><label class="lp-label">Publication<select v-model="form.status" class="field mt-2"><option value="draft">Draft</option><option value="published">Published</option><option value="unpublished">Unpublished</option></select><span class="mt-1 block text-xs font-normal text-slate-500">Only Published portfolios are public.</span></label></section>
<section class="lp-card space-y-4 p-5 sm:p-7"><h2 class="text-xl font-bold">Cover</h2><div class="flex min-h-48 flex-col items-center justify-center gap-4 rounded-xl border border-dashed p-5"><img v-if="preview" :src="preview" class="max-h-52 w-full object-contain" alt="Cover preview"><label class="btn-secondary cursor-pointer">Browse JPG<input type="file" accept="image/jpeg" class="sr-only" @change="cover"></label><button v-if="preview" type="button" class="btn-secondary text-rose-700" @click="form.cover=null;form.remove_cover=true;preview=null">Remove</button><p class="text-xs text-slate-500">JPG only · 5 MB · maximum 3840 × 2160</p><small class="text-rose-600">{{form.errors.cover}}</small></div></section>
<section class="lp-card space-y-4 p-5 sm:p-7"><div class="flex justify-between"><div><h2 class="text-xl font-bold">Portfolio Images</h2><p class="lp-subtitle">{{form.image_ids.length}} / {{imageLimit}}</p></div><button type="button" class="btn-secondary" @click="picker=true">Browse</button></div><small class="text-rose-600">{{form.errors.image_ids}}</small><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><article v-for="(im,i) in chosen" :key="im.id" class="rounded-xl border p-2"><img :src="im.thumbnail_url" class="h-32 w-full rounded-lg object-cover" :alt="im.name"><p class="truncate p-2 text-sm">{{im.name}}</p><button type="button" class="btn-secondary" @click="move(i,-1)">↑</button> <button type="button" class="btn-secondary" @click="move(i,1)">↓</button> <button type="button" class="btn-secondary text-rose-700" @click="toggle(im.id)">Remove</button></article></div></section>
<section class="lp-card space-y-4 p-5 sm:p-7"><div class="flex justify-between"><h2 class="text-xl font-bold">Display Services</h2><button type="button" class="btn-secondary" @click="editor=true">Edit</button></div><label class="lp-label">Currency<select v-model="form.currency_code" class="field mt-2 max-w-xs"><option v-for="(_,code) in currencies" :value="code">{{code}}</option></select></label><div v-for="(s,i) in form.services" :key="s.id||i" class="grid gap-3 rounded-xl border p-4 sm:grid-cols-[1fr_180px]"><label class="flex items-center gap-3"><input v-model="s.enabled" type="checkbox" class="h-5 w-5">{{s.name}}</label><input v-model="s.price" type="number" min="0" step="0.01" class="field" placeholder="Optional price"><small class="text-rose-600">{{form.errors[`services.${i}.price`]}}</small></div></section>
<section class="lp-card space-y-4 p-5 sm:p-7"><h2 class="text-xl font-bold">Payment Details <small>(Optional)</small></h2><p class="lp-subtitle">Encrypted at rest and hidden unless explicitly enabled.</p><label class="flex justify-between rounded-xl border p-4"><span>Display payment details publicly</span><input v-model="form.show_payment_details" type="checkbox" class="h-5 w-5" :disabled="!canManagePayments"></label><UiAlert v-if="form.show_payment_details" tone="warning">Saved payment details will be public.</UiAlert><UiAlert v-if="!canManagePayments">Only the studio owner can manage financial details.</UiAlert><div class="grid gap-5 md:grid-cols-2"><label v-for="x in [['upi_id','UPI ID'],['upi_phone','UPI Phone'],['bank_name','Bank Name'],['account_holder_name','Account Holder'],['account_number','Account Number'],['ifsc','IFSC']]" class="lp-label">{{x[1]}}<input v-model.trim="form[x[0]]" class="field mt-2" :disabled="!canManagePayments" :placeholder="x[0]==='account_number'?(settings.account_number_masked||''):''"><small class="text-rose-600">{{form.errors[x[0]]}}</small></label><label class="lp-label">Account Type<select v-model="form.account_type" class="field mt-2" :disabled="!canManagePayments"><option :value="null">Select</option><option value="savings">Savings</option><option value="current">Current</option></select></label></div></section><UiAlert v-if="Object.keys(form.errors).length" tone="error">Review the fields; your values are preserved.</UiAlert><div class="flex gap-3"><button class="btn-primary" :disabled="form.processing">Save Changes</button><button type="button" class="btn-secondary" @click="form.reset();preview=settings.cover_url">Cancel / Reset</button></div></form></div></div>
<div v-if="picker" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4"><div class="max-h-[85vh] w-full max-w-5xl overflow-auto rounded-2xl bg-white p-5"><div class="flex justify-between"><h2 class="text-xl font-bold">Select Portfolio Images</h2><button class="btn-secondary" @click="picker=false">Done</button></div><p>{{form.image_ids.length}} / {{imageLimit}} selected</p><div class="mt-4 grid grid-cols-2 gap-3 md:grid-cols-4"><button v-for="im in availableImages" type="button" class="rounded-xl border-2 p-1" :class="form.image_ids.includes(im.id)?'border-indigo-600':'border-transparent'" @click="toggle(im.id)"><img :src="im.thumbnail_url" class="h-36 w-full rounded-lg object-cover"><span class="block truncate p-2">{{im.name}}</span></button></div></div></div>
<div v-if="editor" class="fixed inset-0 z-50 grid place-items-center bg-slate-950/60 p-4"><div class="max-h-[85vh] w-full max-w-2xl overflow-auto rounded-2xl bg-white p-5"><div class="flex justify-between"><h2 class="text-xl font-bold">Edit Services</h2><button class="btn-secondary" @click="editor=false">Done</button></div><div v-for="(s,i) in form.services" class="mt-3 flex gap-2"><input v-model.trim="s.name" class="field"><button class="btn-secondary" @click="move(i,-1,form.services)">↑</button><button class="btn-secondary text-rose-700" @click="form.services.splice(i,1)">Remove</button></div><button class="btn-secondary mt-4" @click="form.services.push({id:null,name:'New Service',price:null,enabled:true,is_custom:true})">Add Service</button></div></div></AppShell></template>
